// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8;

contract lab6 {
    uint[] arr;
    uint sum;

    function generate(uint n) external {
        for (uint i = 0; i < n; i++) {
            arr.push(i * i);
        }
    }

    function computeSum() external {
        // 1. Usamos una variable local (stack) para acumular la suma.
        // Operar en el stack cuesta muy poco gas.
        uint localSum = 0;

        // 2. Leemos la longitud del array de storage UNA sola vez
        // y la guardamos en el stack.
        uint length = arr.length;

        // 3. El bucle ahora evalúa la condición usando la variable local
        for (uint i = 0; i < length; i++) {
            // Solo hacemos un acceso a storage aquí: arr[i].
            // Las lecturas y escrituras de la suma se hacen en 'localSum' (stack)
            localSum = localSum + arr[i];
        }

        // 4. Escribimos el resultado final en el storage UNA sola vez al final.
        sum = localSum;
    }
}
